from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    clusters = []  # Initialize list to store separate clusters

    i = 0
    while i < len(paren_string):
        if paren_string[i] == '(':
            count = 1
            j = i + 1
            while j < len(paren_string):
                if paren_string[j] == '(':
                    count += 1
                elif paren_string[j] == ')':
                    count -= 1
                if count == 0:
                    clusters.append(paren_string[i:j+1])  # Step 2: Identify separate clusters of nested parentheses
                    i = j + 1
                    break
                j += 1

    result = [cluster for cluster in clusters]  # Step 3: Separate each cluster into separate strings
    return result

