def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    clusters = []  # Initialize list to store separate clusters

    # Step 2: Identify separate clusters of nested parentheses
    start = 0
    count = 0
    for i, char in enumerate(paren_string):
        if char == '(':
            count += 1
            if count == 1:
                start = i
        elif char == ')':
            count -= 1
            if count == 0:
                clusters.append(paren_string[start:i+1])

    result = []  # Initialize list to store separate strings

    # Step 3: For each cluster, separate it into separate strings and add to the final list
    for cluster in clusters:
        result.append(cluster)

    return result

